out vec4 fragColor;

uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Audio Reactive Uniforms
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;
uniform float u_vol;

// Custom Parameters
uniform float u_speed;
uniform float u_density;
uniform float u_tail_length;
uniform float u_glow_intensity;
uniform float u_color_shift;
uniform float u_nexus_warp;
uniform float u_radiance_bloom;
uniform float u_layer_alpha;

// Pseudo-random hash function
float hash11(float p) {
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

// 2D Rotation matrix
mat2 rot2D(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Rainbow palette function with shift
vec3 getRainbow(float t) {
    vec3 c = 0.5 + 0.5 * cos(6.28318 * (vec3(1.0, 0.66, 0.33) + t + u_color_shift));
    return c;
}

void main() {
    // Correct UVs with aspect ratio
    vec2 uv_orig = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Accumulate color and alpha for deep layering
    vec3 finalColor = vec3(0.0);
    float totalAlpha = 0.0;

    // Background Atmosphere (Initial Layer)
    float vignette = 1.0 - length(uv_orig * 0.8);
    finalColor += vec3(0.005, 0.005, 0.015) * vignette;

    // Draw 4 layers deep with unique transformations
    for(float i = 1.0; i <= 4.0; i++) {
        vec2 uv = uv_orig;

        // Parallax and Scale per layer
        float scale = 1.0 + (i * 0.25);
        uv *= scale;

        // Apply Nexus Warp per layer with varying intensity
        float r = length(uv);
        float twist = sin(r * (1.5 + i * 0.2) - iTime * (0.3 + i * 0.1)) * u_nexus_warp * (1.0 / i);
        uv *= rot2D(twist + u_bass * (0.1 * i));

        // Grid System (Radiant Nexus Columns)
        float density = u_density * (15.0 + i * 5.0);
        float col_id = floor(uv.x * density);
        float col_uv = fract(uv.x * density) - 0.5;

        // Random values per column
        float h = hash11(col_id + i * 54.321);

        // Speed logic with layer variation and audio
        float layer_speed = (u_speed * (0.5 + i * 0.25)) + (u_bass * 0.4);
        float time_offset = iTime * layer_speed + (h * 100.0);

        // Vertical position logic
        float y_pos = fract(uv.y * (0.3 + i * 0.1) - time_offset);

        // Horizontal distance to column center
        float x_dist = abs(col_uv);

        // Intensity based on vertical distance (the tail)
        float tail_fade = pow(y_pos, 5.0 / (u_tail_length + 0.01));

        // Horizontal sharpness of the light beam
        float beam = smoothstep(0.12, 0.0, x_dist * (10.0 + i * 4.0));

        // Color for this layer
        vec3 starCol = getRainbow(h + iTime * 0.03 + i * 0.2);

        // Audio reaction
        starCol *= (1.0 + u_treble * 1.0 + u_mid * 0.3);

        // Main beam intensity
        float intensity = tail_fade * beam;

        // Add a bright "spark" or "nexus core" at the head
        float head_dist = distance(vec2(col_uv, y_pos), vec2(0.0, 0.02));
        float head = smoothstep(0.06, 0.0, head_dist);
        intensity += head * 2.5;

        // Radiance/Glow calculation
        float glow = 0.012 / (x_dist + 0.015);
        glow *= tail_fade;

        // Core Bloom
        float bloom = 0.015 / (head_dist + 0.01);

        // Layer Transparency Logic: deeper layers are dimmer/more transparent
        float layerAlpha = u_layer_alpha * (1.0 / i);

        // Additive contribution with alpha weighting
        vec3 layerContribution = starCol * (intensity + (glow + bloom) * u_glow_intensity * u_radiance_bloom * 0.3);
        finalColor += layerContribution * layerAlpha;
    }

    // Central Radiant Nexus Core (Overall Atmosphere)
    float center_glow = 0.04 / (length(uv_orig) + 0.04);
    finalColor += getRainbow(u_color_shift) * center_glow * (u_bass * 0.5 + 0.1) * u_radiance_bloom;

    // Tone mapping (Exposure)
    finalColor = 1.0 - exp(-finalColor * 2.0);

    // Gamma correction
    finalColor = pow(finalColor, vec3(0.4545));

    fragColor = vec4(finalColor, 1.0);
}
